define({"topics":[{"title":"Removing the magnet service access trim","shortdesc":"<p class=\"shortdesc\">Removes the service access trim. The trim panel covers the screws securing the front and rear service access panels.<\/p>","href":"t_RemovingTheServiceAccessTrim_5.html","attributes":{"data-id":"id_2002821"},"menu":{"hasChildren":false},"tocID":"id_2002821-d46e18771","topics":[]},{"title":"Removing the magnet front service access panel","shortdesc":"<p class=\"shortdesc\">Removes the front service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheFrontServiceAccessPanel_4.html","attributes":{"data-id":"id_2002823"},"menu":{"hasChildren":false},"tocID":"id_2002823-d46e18875","topics":[]},{"title":"Removing the magnet rear service access panel","shortdesc":"<p class=\"shortdesc\">Removes the rear service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheRearServiceAccessPanel_3.html","attributes":{"data-id":"id_2002966"},"menu":{"hasChildren":false},"tocID":"id_2002966-d46e18979","topics":[]},{"title":"Removing the magnet service access vent","shortdesc":"<p class=\"shortdesc\">Removes the service access vent from the magnet enclosure allowing a ladder to stand close to the magnet on the left-hand side.<\/p>","href":"t_RemovingTheServiceAccessVent_2.html","attributes":{"data-id":"id_2002970"},"menu":{"hasChildren":false},"tocID":"id_2002970-d46e19083","topics":[]},{"title":"Removing the magnet upper service access panel","shortdesc":"<p class=\"shortdesc\">Removes the upper service access panel allowing access to components mounted on top of the magnet.<\/p>","href":"t_RemovingTheUpperServiceAccessPanel_2.html","attributes":{"data-id":"id_2002968"},"menu":{"hasChildren":false},"tocID":"id_2002968-d46e19187","topics":[]}]});